mapper.delete:
DELETE FROM tb_emp
WHERE hosp_div_id = #{hospitalDomain}
  AND emp_id = #{userId}
  AND role_cd = 'USER'
  AND auth_st = 'INACTIVE'

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM tb_ward
    WHERE hosp_div_id = #{hospitalDomain}
      AND ward_id = #{wardId}
)

SELECT ward_id
FROM tb_emp
WHERE hosp_div_id = #{hospitalDomain}
  AND emp_id = #{userId}

SELECT phone_no
FROM tb_emp
WHERE hosp_div_id = #{hospitalDomain}
  AND emp_id = #{userId}

SELECT EXISTS (
    SELECT 1
    FROM tb_emp
    WHERE hosp_div_id = #{hospitalDomain}
      AND emp_id <> #{userId}
      AND role_cd = 'USER'
      AND auth_st = 'APPROVED'
      AND phone_no = #{phoneNumber}
)
